import{_ as e,o,c as i,a3 as r}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Mini painel de atalhos do processo","description":"","frontmatter":{"title":"Mini painel de atalhos do processo","id":"eproc-mini-painel-atalhos","plataforma":"eproc","grupo":"Painel do processo","plano":"free","desde":"1.0.2","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-mini-painel-atalhos"}]]},"headers":[],"relativePath":"funcionalidades/eproc-mini-painel-atalhos.md","filePath":"funcionalidades/eproc-mini-painel-atalhos.md"}'),s={name:"funcionalidades/eproc-mini-painel-atalhos.md"};function n(l,a,t,p,d,c){return o(),i("div",null,a[0]||(a[0]=[r('<h1 id="mini-painel-de-atalhos-do-processo" tabindex="-1">Mini painel de atalhos do processo <a class="header-anchor" href="#mini-painel-de-atalhos-do-processo" aria-label="Permalink to &quot;Mini painel de atalhos do processo&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>A página do processo é longa, e a tabela de eventos costuma ficar várias telas abaixo. Este recurso mostra um pequeno painel lateral com atalhos que levam direto a cada seção. Ele pode ser expandido numa barra lateral com um minimapa da página.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo. O mini painel fica à esquerda. A barra expandida, com o minimapa, fica na borda direita da janela.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um processo. O mini painel mostra atalhos para Lembretes, Assuntos, Partes, Minutas, Informações adicionais, Ações e Eventos.</li><li>Clique num atalho para rolar até a seção correspondente.</li><li>Para navegar com mais detalhe, clique em <strong>Abrir sidebar expandida</strong>. A barra lateral mostra um minimapa da página, com os blocos de eventos. Clique ou arraste no minimapa para ir a qualquer ponto.</li><li>Para voltar ao mini painel, clique em <strong>Reduzir para mini painel</strong>.</li></ol><p>A escolha entre o mini painel e a barra expandida é lembrada e vale para todos os endereços do eproc.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Quando o menu lateral do eproc é recolhido, o mini painel se reposiciona no canto esquerdo.</li><li>Os <a href="./eproc-destaques-trecho">destaques de trecho</a> aparecem também no minimapa, com as cores escolhidas.</li></ul>',12)]))}const h=e(s,[["render",n]]);export{u as __pageData,h as default};
